import sys
sys.setrecursionlimit(10000)
V=range(101)
def adj(rev):
    return {i:sorted([j for j in V if 0<j-i<=2], reverse=rev) for i in V}
def rec_dfs(A):
    order=[]; seen=set()
    def dfs(u):
        seen.add(u); order.append(u)
        for v in A[u]:
            if v not in seen: dfs(v)
    dfs(0); return order
def after50(order): return len(order)-order.index(50)-1
o=rec_dfs(adj(True))
print('decreasing lists, recursive DFS:', o[:4], '...', o[49:54], '...', o[-3:], '-> after 50:', after50(o))
# trap checks from commonTrap
print('increasing lists, recursive DFS -> after 50:', after50(rec_dfs(adj(False))))
A=adj(True); st=[0]; seen=set(); o2=[]
while st:
    u=st.pop()
    if u in seen: continue
    seen.add(u); o2.append(u)
    for v in A[u]:
        if v not in seen: st.append(v)
print('explicit stack pushing lists in order -> after 50:', after50(o2))
